// ---------------------------------------------------------------------------
// Hermes Arena — concept "Classical Messenger (cutout)"
// GENERATED by concepts/cutout/classic/build.py from concepts/refs/classic-34.png
// (edit concepts/cutout/classic/runtime.js and the slicing data in build.py, then rebuild).
//
// A cutout puppet: the mockup itself, sliced into parts (cloak, staff, upper arms, forearms,
// thighs, shins+feet, torso, head, mantle) that are rotated about their pivots by a small rig.
// Each part is stored as one grey PNG holding two premultiplied coverage maps (ink share on top,
// paper share below; they add up to the part's alpha), so
// the runtime can print it in any ink: own ink as drawn, player 2+ re-inked, cached per ink.
// ---------------------------------------------------------------------------
(function () {
  const RIG = /*@RIG@*/null;
  const PARTS = /*@PARTS@*/[];
  const OWN = RIG.ink;
  const PAPER_C = RIG.paper;
  const RAD = Math.PI / 180;
  const BY = {};
  for (const p of PARTS) BY[p.name] = p;

  // ---- poses ------------------------------------------------------------------------------
  // The concept page shows the drawing at rest (every part where the mockup has it), breathing.
  // The game drives these parts from the animation skeleton instead (src/skins/classic.js).
  const POSES = { stand: {} };

  // ---- 2D affine helpers: [a, b, c, d, e, f] like DOMMatrix --------------------------------
  const mul = (m, n) => [
    m[0] * n[0] + m[2] * n[1], m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3], m[1] * n[2] + m[3] * n[3],
    m[0] * n[4] + m[2] * n[5] + m[4], m[1] * n[4] + m[3] * n[5] + m[5],
  ];
  const app = (m, p) => [m[0] * p[0] + m[2] * p[1] + m[4], m[1] * p[0] + m[3] * p[1] + m[5]];
  const I = [1, 0, 0, 1, 0, 0];
  // rotate (deg) and scale (sx, sy) about pivot p, then translate by t
  function about(p, deg, sx, sy, t) {
    const c = Math.cos(deg * RAD), s = Math.sin(deg * RAD);
    sx = sx || 1; sy = sy || 1;
    const a = c * sx, b = s * sx, cc = -s * sy, d = c * sy;
    const tx = (t ? t[0] : 0), ty = (t ? t[1] : 0);
    return [a, b, cc, d, p[0] - (a * p[0] + cc * p[1]) + tx, p[1] - (b * p[0] + d * p[1]) + ty];
  }
  const ang = (v) => Math.atan2(v[1], v[0]) / RAD;

  // world matrices (source px -> source px) for every part: the rest pose plus a breath
  function solve(pose, time) {
    const t = time || 0;
    const br = Math.sin(t * Math.PI * 2 / 3.4);
    const brLag = Math.sin(t * Math.PI * 2 / 3.4 - 0.7);
    const M = {};
    for (const p of PARTS) M[p.name] = I;
    const hip = RIG.joints.hip;
    const T = about(hip, 0, 1, 1 + 0.005 * (1 + br));
    for (const n of ['torso', 'mantle', 'cloak', 'armB_up', 'armB_lo', 'staff', 'armF_up', 'foreF', 'fistF']) M[n] = T;
    M.head = mul(T, about(BY.head.pivot, 0.7 * brLag, 1, 1, [0, -0.5 * (1 + brLag)]));
    M.hatwing = M.head;
    return { M, z: null };
  }

  // ---- part canvases ------------------------------------------------------------------------
  const mk = (w, h) => { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; };
  const BASE = {};   // name -> { paper, inkMask }  (built once from the grey maps)
  const CACHE = new Map(); // ink -> { name -> { full, half } }

  function decode(p) {
    return new Promise((res, rej) => {
      const im = new Image();
      im.onload = () => res(im);
      im.onerror = () => rej(new Error('cutout part ' + p.name + ' failed to decode'));
      im.src = p.src;
    }).then((im) => {
      const w = p.w, h = p.h;
      const c = mk(w, h * 2), x = c.getContext('2d');
      x.drawImage(im, 0, 0);
      const D = x.getImageData(0, 0, w, h * 2).data; // once, at load time
      const paper = mk(w, h), inkMask = mk(w, h);
      const pd = paper.getContext('2d').createImageData(w, h);
      const kd = inkMask.getContext('2d').createImageData(w, h);
      const pc = [parseInt(PAPER_C.slice(1, 3), 16), parseInt(PAPER_C.slice(3, 5), 16), parseInt(PAPER_C.slice(5, 7), 16)];
      for (let i = 0, n = w * h; i < n; i++) {
        const ink = D[i * 4], pap = D[(i + n) * 4];
        pd.data[i * 4] = pc[0]; pd.data[i * 4 + 1] = pc[1]; pd.data[i * 4 + 2] = pc[2]; pd.data[i * 4 + 3] = pap;
        kd.data[i * 4 + 3] = ink;
      }
      paper.getContext('2d').putImageData(pd, 0, 0);
      inkMask.getContext('2d').putImageData(kd, 0, 0);
      BASE[p.name] = { paper, inkMask };
    });
  }

  // Prints are cached per ink: own ink and player 2's are built in `ready`; any other ink is
  // built on first use and the cache is an LRU of CACHE_MAX inks (own ink pinned), so a varying
  // ink cannot leak canvases. Flashes and fades belong in globalAlpha or an overlay, not in inks.
  const CACHE_MAX = 4;
  function printed(ink) {
    let set = CACHE.get(ink);
    if (set) {
      if (ink !== OWN) { CACHE.delete(ink); CACHE.set(ink, set); } // most recent last
      return set;
    }
    set = {};
    for (const p of PARTS) {
      const B = BASE[p.name];
      const tint = mk(p.w, p.h), tx = tint.getContext('2d');
      tx.drawImage(B.inkMask, 0, 0);
      tx.globalCompositeOperation = 'source-in';
      tx.fillStyle = ink;
      tx.fillRect(0, 0, p.w, p.h);
      const full = mk(p.w, p.h), fx = full.getContext('2d');
      // paper share and ink share are premultiplied parts of one coverage: add them
      fx.drawImage(B.paper, 0, 0);
      fx.globalCompositeOperation = 'lighter';
      fx.drawImage(tint, 0, 0);
      fx.globalCompositeOperation = 'source-over';
      // half-size print for small scales (smoother than minifying the halftone on the fly)
      const hw = Math.ceil(p.w / 2), hh = Math.ceil(p.h / 2);
      const half = mk(hw, hh), hx = half.getContext('2d');
      hx.imageSmoothingEnabled = true;
      hx.imageSmoothingQuality = 'high';
      hx.drawImage(full, 0, 0, hw, hh);
      // rim for the half print: the part's coverage grown by ~1 source px (0.44 game px) in
      // ink. All rims are drawn before all parts, so only the figure's outer silhouette
      // thickens; seams between parts stay covered.
      const rim = mk(hw + 2, hh + 2), rx = rim.getContext('2d');
      for (let k = 0; k < 8; k++) {
        const a = k * Math.PI / 4;
        rx.drawImage(half, 1 + 0.55 * Math.cos(a), 1 + 0.55 * Math.sin(a));
      }
      rx.globalCompositeOperation = 'source-in';
      rx.fillStyle = ink;
      rx.fillRect(0, 0, hw + 2, hh + 2);
      set[p.name] = { full, half, rim };
    }
    // soft contact shadow (an ink ellipse fading out), drawn under each sandal
    const sh = mk(64, 16), sx = sh.getContext('2d');
    sx.translate(32, 8);
    sx.scale(1, 0.25);
    const gr = sx.createRadialGradient(0, 0, 0, 0, 0, 31);
    gr.addColorStop(0, ink);
    gr.addColorStop(0.55, ink);
    gr.addColorStop(1, 'rgba(0,0,0,0)');
    sx.fillStyle = gr;
    sx.beginPath(); sx.arc(0, 0, 31, 0, Math.PI * 2); sx.fill();
    set.shadow = sh;
    CACHE.set(ink, set);
    while (CACHE.size > CACHE_MAX) {
      for (const k of CACHE.keys()) { if (k !== OWN) { CACHE.delete(k); break; } }
    }
    return set;
  }

  const ready = Promise.all(PARTS.map(decode)).then(() => {
    printed(OWN);
    if (typeof INK !== 'undefined' && INK.sanguine) printed(INK.sanguine); // P2, no first-draw hitch
  });

  // ---- draw ---------------------------------------------------------------------------------
  const ORDER = PARTS.filter((p) => !p.extra).map((p) => p.name);
  // sandal soles (source px): centre x and half width, for the contact shadows
  const SOLES = [['footB', 124, 33], ['footF', 268, 44]];
  function draw(g, pose, opts) {
    if (!BASE[PARTS[PARTS.length - 1].name]) return; // not decoded yet
    const ink = !opts || !opts.ink || opts.ink === INK.blue ? OWN : opts.ink;
    const set = printed(ink);
    const { M, z } = solve(pose, opts && opts.time);
    const s = RIG.scale;
    const T = g.getTransform();
    const dev = Math.sqrt(Math.abs(T.a * T.d - T.b * T.c)) * s; // device px per source px
    const useHalf = dev < 0.62;
    const only = API.only; // debug: draw a subset of parts
    const list = z || ORDER;
    g.save();
    g.imageSmoothingEnabled = true;
    g.imageSmoothingQuality = 'high';
    g.scale(s, s);
    g.translate(-RIG.origin[0], -RIG.origin[1]);
    if (!only) {
      const a0 = g.globalAlpha;
      g.globalAlpha = a0 * 0.2;
      const ry = 2.2 / s; // about 2 game px tall
      for (const [f, cx, hw] of SOLES) {
        const m = M[f];
        g.drawImage(set.shadow, cx + m[4] - hw * 1.2, RIG.origin[1] + m[5] - ry * 0.45, hw * 2.4, ry);
      }
      g.globalAlpha = a0;
    }
    for (let pass = useHalf ? 0 : 1; pass < 2; pass++) {
      for (const name of list) {
        if (only && only.indexOf(name) < 0) continue;
        const p = BY[name], m = M[name], c = set[name];
        g.save();
        g.transform(m[0], m[1], m[2], m[3], m[4], m[5]);
        if (pass === 0) g.drawImage(c.rim, p.x - 2, p.y - 2, p.w + 4, p.h + 4);
        else g.drawImage(useHalf ? c.half : c.full, p.x, p.y, p.w, p.h);
        g.restore();
      }
    }
    g.restore();
  }

  const API = window.CONCEPT = {
    name: 'Classical Messenger (cutout)',
    tagline: 'the mockup itself, sliced into a rigged cutout puppet',
    height: RIG.height,
    print: { paper: PAPER_C, ink: OWN, grain: 0.15 },
    poses: POSES,
    solve,
    ready,
    draw,
  };
})();
